/**
 * results-agent.ts
 *
 * ResultsAgent — rank / personal best / season best, per docs/roadmap.md
 * / docs/ai-architecture.md ("ResultsAgent — rank/PB/SB with sport-aware
 * cross-validation"). This was the last content generated by the original
 * monolithic prompt in auto-populate.ts; every other field had already
 * moved to its own dedicated agent (M4–M11). Extracted here purely for
 * structural symmetry with the other seven agents — same research +
 * extraction + validation shape, no behavioural change.
 *
 * PB/SB cross-validation (a season best cannot be faster than a career
 * personal best) is unchanged from M3.1: performance-marks.ts's
 * crossValidatePerformanceMarks() is still the single implementation,
 * called here instead of from auto-populate.ts.
 */

import { openai } from "@workspace/integrations-openai-ai-server";
import { logger } from "./logger.js";
import { callPerplexity } from "./perplexity-client.js";
import { withAiConcurrencyLimit } from "./ai-concurrency.js";
import { withRetry } from "./retry.js";
import { crossValidatePerformanceMarks } from "./performance-marks.js";
import type { AthleteStub } from "./athlete-stub.js";

export interface ResultsUpdate {
  worldRank: number | null;
  worldRankDelta: number;
  nationalRank: number | null;
  personalBest: string | null;
  seasonBest: string | null;
}

const EMPTY_RESULTS: ResultsUpdate = {
  worldRank: null,
  worldRankDelta: 0,
  nationalRank: null,
  personalBest: null,
  seasonBest: null,
};

async function researchResults(
  athlete: AthleteStub,
): Promise<{ research: string; citations: string[] }> {
  const today = new Date().toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });
  const currentYear = new Date().getFullYear();
  try {
    const { research, citations } = await callPerplexity({
      label: "results-agent research",
      maxTokens: 2048,
      systemPrompt: `You are an elite sports intelligence researcher. Search the web thoroughly and return accurate, current, cited information. Today's date is ${today}. Be specific — include exact ranks and exact performance marks. Never fabricate information.`,
      userPrompt: `Research ${athlete.name} (${athlete.sport} — ${athlete.event}, ${athlete.nationality}):

1. RANKINGS: Current world ranking, current national ranking, and how the world ranking has changed over the past year (delta).
2. PERFORMANCE MARKS: Personal best and season best (${currentYear}) times/marks, each with the date it was set. For DH MTB this is a race finishing time like "4:31.18", not a placement. Look for actual timed or measured results — not a placement or medal.

Cite your sources. If a figure isn't available from real sources, say so rather than guessing.`,
    });
    logger.info(
      { athleteId: athlete.id, name: athlete.name, length: research.length, citationCount: citations.length },
      "results-agent: research complete",
    );
    return { research, citations };
  } catch (err) {
    logger.warn(
      { err, athleteId: athlete.id, name: athlete.name },
      "results-agent: research failed — no rank/PB/SB update this run",
    );
    return { research: "", citations: [] };
  }
}

const SYSTEM_PROMPT = `You are a sports intelligence data engine extracting ranking and performance-mark data. Return ONLY valid JSON — no markdown, no explanation.

Rules:
- ACCURACY FIRST: use the provided research as your primary source of truth. Do not contradict it.
- If the research does not cover a field, return null for it — do not guess or fabricate a plausible-looking number.
- personalBest/seasonBest must be an actual measured performance mark ONLY, never a race placement or event name. Format examples by sport: DH MTB = "4:31.18" (race time), Sprint = "9.87s", 800m = "1:43.22", Long jump = "8.95m", Weightlifting = "148kg snatch", Cycling power = "6.8 W/kg". If unknown, return null.`;

const USER_PROMPT = (a: AthleteStub, research: string, citations: string[]): string => `
Athlete: ${a.name} (${a.sport} — ${a.event}, ${a.nationality})

${citations.length > 0
  ? `VERIFIED CITATION URLs:
${citations.map((c, i) => `${i + 1}. ${c}`).join("\n")}

`
  : ""}${research
  ? `VERIFIED RESEARCH:
\`\`\`
${research}
\`\`\``
  : `ABORT: No verified research is available. Return { "worldRank": null, "worldRankDelta": 0, "nationalRank": null, "personalBest": null, "seasonBest": null }.`}

Extract as JSON:
{
  "worldRank": <integer or null>,
  "worldRankDelta": <integer, negative = improved>,
  "nationalRank": <integer or null>,
  "personalBest": <string or null>,
  "seasonBest": <string or null>
}
`;

/**
 * Runs the ResultsAgent: dedicated Perplexity research + GPT-4o extraction
 * for world/national rank and personal-best/season-best marks, with the
 * existing PB<=SB cross-validation applied before returning. Never throws
 * — a failure at any stage returns the all-null/zero default rather than
 * blocking the rest of the pipeline.
 */
export async function runResultsAgent(athlete: AthleteStub): Promise<ResultsUpdate> {
  const { research, citations } = await researchResults(athlete);
  if (!research) return EMPTY_RESULTS;

  try {
    const response = await withAiConcurrencyLimit(() =>
      withRetry(
        () =>
          openai.chat.completions.create({
            model: "gpt-4o",
            max_completion_tokens: 512,
            messages: [
              { role: "system", content: SYSTEM_PROMPT },
              { role: "user", content: USER_PROMPT(athlete, research, citations) },
            ],
            response_format: { type: "json_object" },
          }),
        { label: "results-agent extraction" },
      ),
    );
    const raw = response.choices[0]?.message?.content;
    if (!raw) return EMPTY_RESULTS;

    const s = JSON.parse(raw) as Record<string, unknown>;

    const { personalBest, seasonBest } = crossValidatePerformanceMarks(
      typeof s.personalBest === "string" ? s.personalBest : null,
      typeof s.seasonBest === "string" ? s.seasonBest : null,
      { athleteId: athlete.id, name: athlete.name },
    );

    return {
      worldRank: typeof s.worldRank === "number" ? s.worldRank : null,
      worldRankDelta: typeof s.worldRankDelta === "number" ? s.worldRankDelta : 0,
      nationalRank: typeof s.nationalRank === "number" ? s.nationalRank : null,
      personalBest,
      seasonBest,
    };
  } catch (err) {
    logger.warn(
      { err, athleteId: athlete.id, name: athlete.name },
      "results-agent: extraction failed — no rank/PB/SB update this run",
    );
    return EMPTY_RESULTS;
  }
}
